input.command:
$ErrorActionPreference='SilentlyContinue'
Write-Output "== 工作目录 =="
Get-Location | Select-Object -ExpandProperty Path

Write-Output "`n== 联网探测 (访问 example.com) =="
try {
  $r = Invoke-WebRequest -Uri 'https://example.com' -UseBasicParsing -TimeoutSec 8
  Write-Output ("网络: 可访问, HTTP " + $r.StatusCode)
} catch {
  Write-Output ("网络: 被拦/失败 -> " + $_.Exception.Message)
}

Write-Output "`n== 工作目录外写文件探测 =="
$out = Join-Path $env:TEMP 'cc_sandbox_probe.txt'
try {
  Set-Content -Path $out -Value 'probe' -Encoding utf8 -ErrorAction Stop
  Write-Output ("写外部目录: 成功 -> " + $out)
  Remove-Item $out -Force -ErrorAction SilentlyContinue
} catch {
  Write-Output ("写外部目录: 被拦/失败 -> " + $_.Exception.Message)
}
Write-Output ("TEMP 路径: " + $env:TEMP)
